// Main computational kernel
//
// All loop nests over data dimensions (i, j, k) are expressed using Noarr
// traversers. Inner products over k are implemented as traversals over
// 1‑D views of rows/columns, so that the innermost traversal is contiguous
// in memory and vectorization‑friendly.
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Problem size (length in dimension 'i')
	const std::size_t n = A | get_length<'i'>();

	// Non‑owning reference bags so that we can cheaply create views
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// Proto‑structures reused many times
	constexpr auto rename_j_to_k = noarr::rename<'j', 'k'>(); // j -> k
	constexpr auto rename_i_to_k = noarr::rename<'i', 'k'>(); // i -> k

	// ---------------------------------------------------------------------
	// 1) LU factorization: A = L * U  (in-place, Doolittle scheme)
	//
	// Original scheme:
	//   for i = 0..N-1:
	//     for j = 0..i-1:
	//       A[i][j] = (A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j]) / A[j][j];
	//     for j = i..N-1:
	//       A[i][j] = A[i][j] - sum_{k=0..i-1} A[i][k] * A[k][j];
	//
	// Here, all sums over k are expressed as Noarr traversals over 1‑D
	// row/column views of A sharing a common artificial 'k' dimension.
	// ---------------------------------------------------------------------
	noarr::traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// Fixed row index i
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// View of the whole i-th row: A[i][j]
		auto row_i_j = A_ref ^ noarr::fix<'i'>(i_idx);           // dim: 'j'
		// Same physical row, but with dimension renamed to 'k' for inner products
		auto row_i_k = row_i_j.get_ref() ^ rename_j_to_k;        // dim: 'k'

		// ----- Lower part: j in [0, i)  -> compute L(i,j) -----
		if (i_idx > 0) {
			auto slice_j_lower = noarr::slice<'j'>(0, i_idx);    // j = 0..i-1

			noarr::traverser(row_i_j)
				.order(slice_j_lower)
				.for_each([&](auto s_j) {
					const std::size_t j_idx = get_index<'j'>(s_j);

					// Start with A[i][j]
					num_t w = row_i_j[s_j];

					// Compute sum_{k=0..j-1} A[i][k] * A[k][j] using
					// 1‑D views over a common 'k' dimension.
					if (j_idx > 0) {
						// Column view: A[k][j]
						auto col_j_i = A_ref ^ noarr::fix<'j'>(j_idx);       // dim: 'i'
						auto col_j_k = col_j_i.get_ref() ^ rename_i_to_k;    // dim: 'k'

						auto slice_k = noarr::slice<'k'>(0, j_idx);          // k = 0..j-1

						noarr::traverser(row_i_k, col_j_k)
							.order(slice_k)
							.for_each([&](auto s_k) {
								w -= row_i_k[s_k] * col_j_k[s_k];
							});
					}

					// Divide by diagonal element U[j][j] (already computed)
					num_t diag_j = A_ref[noarr::idx<'i', 'j'>(j_idx, j_idx)];
					row_i_j[s_j] = w / diag_j; // L(i,j)
				});
		}

		// ----- Upper part (including diagonal): j in [i, N)  -> compute U(i,j) -----
		auto slice_j_upper = noarr::slice<'j'>(i_idx, n - i_idx); // j = i..N-1
		noarr::traverser(row_i_j)
			.order(slice_j_upper)
			.for_each([&](auto s_j) {
				const std::size_t j_idx = get_index<'j'>(s_j);

				// Start with A[i][j]
				num_t w = row_i_j[s_j];

				// Compute sum_{k=0..i-1} A[i][k] * A[k][j]
				if (i_idx > 0) {
					auto col_j_i = A_ref ^ noarr::fix<'j'>(j_idx);         // dim: 'i'
					auto col_j_k = col_j_i.get_ref() ^ rename_i_to_k;      // dim: 'k'

					auto slice_k = noarr::slice<'k'>(0, i_idx);            // k = 0..i-1

					noarr::traverser(row_i_k, col_j_k)
						.order(slice_k)
						.for_each([&](auto s_k) {
							w -= row_i_k[s_k] * col_j_k[s_k];
						});
				}

				// U(i,j)
				row_i_j[s_j] = w;
			});
	});

	// ---------------------------------------------------------------------
	// 2) Forward substitution: solve L * y = b
	//
	//   for i = 0..N-1:
	//     y[i] = b[i] - sum_{j=0..i-1} L[i][j] * y[j];
	//
	// Implemented as a traversal over 'i', and inner products over
	// a common 1‑D 'k' dimension (k == j).
	// ---------------------------------------------------------------------
	noarr::traverser(y).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// Start with b[i]
		num_t w = b_ref[s_i];

		if (i_idx > 0) {
			// Row L[i,*]
			auto L_row_j = A_ref ^ noarr::fix<'i'>(i_idx);        // dim: 'j'
			auto L_row_k = L_row_j.get_ref() ^ rename_j_to_k;     // dim: 'k'

			// y[0..i-1] as 1‑D over 'k'
			auto y_k = y_ref ^ rename_i_to_k;                     // dim: 'k'

			auto slice_k = noarr::slice<'k'>(0, i_idx);           // k = 0..i-1

			noarr::traverser(L_row_k, y_k)
				.order(slice_k)
				.for_each([&](auto s_k) {
					w -= L_row_k[s_k] * y_k[s_k];
				});
		}

		y_ref[s_i] = w;
	});

	// ---------------------------------------------------------------------
	// 3) Backward substitution: solve U * x = y
	//
	//   for i = N-1 .. 0:
	//     x[i] = (y[i] - sum_{j=i+1..N-1} U[i][j] * x[j]) / U[i][i];
	//
	// We traverse an "inverse" index inv = 0..N-1 and map i = N-1-inv,
	// again expressing the inner sum as a traversal over a 'k' dimension.
	// ---------------------------------------------------------------------
	noarr::traverser(x).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		const std::size_t inv   = get_index<'i'>(s_inv);
		const std::size_t i_idx = n - 1 - inv; // descending i

		// y[i]
		num_t w = y_ref[noarr::idx<'i'>(i_idx)];

		// Sum over j = i+1 .. N-1  (as k = j)
		if (i_idx + 1 < n) {
			// Row U[i,*]
			auto U_row_j = A_ref ^ noarr::fix<'i'>(i_idx);        // dim: 'j'
			auto U_row_k = U_row_j.get_ref() ^ rename_j_to_k;     // dim: 'k'

			// x as 1‑D over 'k'
			auto x_k = x_ref ^ rename_i_to_k;                     // dim: 'k'

			const std::size_t start = i_idx + 1;
			const std::size_t len   = n - start;                  // may be 0

			auto slice_k = noarr::slice<'k'>(start, len);         // k = i+1..N-1

			noarr::traverser(U_row_k, x_k)
				.order(slice_k)
				.for_each([&](auto s_k) {
					w -= U_row_k[s_k] * x_k[s_k];
				});
		}

		num_t diag = A_ref[noarr::idx<'i', 'j'>(i_idx, i_idx)];
		x_ref[noarr::idx<'i'>(i_idx)] = w / diag;
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
