void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension
	std::size_t n = A | get_length<'i'>();

	// -------------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// Rewritten using a single j-loop per i:
	//   max_k = (j < i ? j : i);
	//   w = A[i][j] - sum_{k=0..max_k-1} A[i][k]*A[k][j];
	//   if (j < i) A[i][j] = w / A[j][j];
	//   else       A[i][j] = w;
	//
	// Implementation notes:
	// - We use a traverser over 'i' (rows) and then over 'j' (columns) to get
	//   a cache-friendly row-major traversal.
	// - The inner k-loop is kept as a plain C++ loop, but all element accesses
	//   are expressed via Noarr bags and index states. We pre-build states
	//   such as {i} and {j} once per iteration to minimize index recomputation.
	// -------------------------------------------------------------------------
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; remaining dimension is 'j'
		auto s_i      = trav_i.state();
		std::size_t i = get_index<'i'>(s_i);

		// State containing just the current row index, reusable in inner loops
		auto state_i = noarr::idx<'i'>(i);

		trav_i.for_each([&](auto state_ij) {
			// state_ij contains both 'i' and 'j' for A
			std::size_t j = get_index<'j'>(state_ij);

			// State with just current column index, reusable in k-loop
			auto state_j = noarr::idx<'j'>(j);

			// Start from the current matrix element
			num_t w = A[state_ij];

			// Number of terms in the dot product:
			// - for j < i : sum over k=0..j-1
			// - for j >= i: sum over k=0..i-1
			std::size_t max_k = (j < i) ? j : i;

			// Accumulate w -= A[i][k] * A[k][j]
			for (std::size_t k = 0; k < max_k; ++k) {
				// Build states {i,k} and {k,j} cheaply using state composition.
				auto s_ik = state_i & noarr::idx<'j'>(k);
				auto s_kj = noarr::idx<'i'>(k) & state_j;

				w -= A[s_ik] * A[s_kj];
			}

			if (j < i) {
				// Lower part: divide by diagonal A[j][j]
				auto s_jj = noarr::idx<'i', 'j'>(j, j);
				A[state_ij] = w / A[s_jj];
			} else {
				// Upper part: store the final value directly
				A[state_ij] = w;
			}
		});
	});

	// -------------------------------------------------------------------------
	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We again traverse over 'i' using a traverser and compute each y[i] with
	// a reduction over j < i. All accesses use Noarr states; we reuse states
	// {i} and {j} to keep indexing overhead low.
	// -------------------------------------------------------------------------
	traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i      = trav_i.state();
		std::size_t i = get_index<'i'>(s_i);
		auto state_i  = noarr::idx<'i'>(i);

		// Start from b[i]
		num_t w = b[state_i];

		// Iterate over all j, but use only j < i
		trav_i.for_each([&](auto state_ij) {
			std::size_t j = get_index<'j'>(state_ij);
			if (j < i) {
				auto state_j = noarr::idx<'i'>(j);
				// A[i][j] is A[state_ij] since state_ij already has {i,j}
				w -= A[state_ij] * y[state_j];
			}
		});

		y[state_i] = w;
	});

