	// We implement this with an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	//
	// This keeps the outer loop expressed via a Noarr traverser while
	// preserving the original dependency order (x[i] depends on x[j>i]).
	// -------------------------------------------------------------------------
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv      = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i   = n - 1 - inv;

		// States {i} and {i,i}, reused below
		auto state_i  = noarr::idx<'i'>(i);
		auto state_ii = noarr::idx<'i', 'j'>(i, i);

		// Start from y[i]
		num_t w = y[state_i];

