	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We keep the outer loop ascending using an "inverse" index inv, but
	// still traverse data in a layout-agnostic way.  The inner j-loop is
	// once again expressed as a traversal over a 1D 'k' dimension sliced
	// to k in [i+1, N).
	// ------------------------------------------------------------------
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_inv = trav_i.state();
		std::size_t inv   = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv; // map inv = 0..N-1 to i = N-1..0

		num_t w = y_ref.template at<'i'>(i_idx);

		// Row of U (i-th row of A) as a vector over 'k':
		//   A_row_k[k] == A[i][k]
		auto A_row_k = A_ref
			^ fix<'i'>(i_idx)
			^ rename<'j', 'k'>();

		// x as a vector over 'k':
		//   x_k[k] == x[k]
		auto x_k = x_ref ^ rename<'i', 'k'>();

		std::size_t start_k = i_idx + 1;
		std::size_t len_k   = (start_k < n) ? (n - start_k) : 0;

		if (len_k > 0) {
			// Accumulate w -= sum_{k=i+1..N-1} A[i][k] * x[k]
			traverser(A_row_k, x_k)
				.order(slice<'k'>(start_k, len_k))
				.for_each([&](auto s_k) {
					w -= A_row_k[s_k] * x_k[s_k];
				});
		}

		x_ref.template at<'i'>(i_idx) =
			w / A_ref.template at<'i', 'j'>(i_idx, i_idx);
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
